ScriptText:
$e = Get-WinEvent -FilterHashtable @{
  LogName = 'Microsoft-Windows-PowerShell/Operational'
  Id = 4104
  StartTime = $runStart
} | Where-Object {
  $_.Message -match 'TFM candidate v3'
} | Select-Object -First 1

[pscustomobject]@{
  UploadHttp       = $e.Message -match '(?i)(Invoke-WebRequest|\biwr\b|\bwget\b|\bcurl\b)'
  UploadFile       = $e.Message -match '(?i)(-InFile\b|\bInFile\b)'
  UploadPost       = $e.Message -match '(?i)(-Method\s+POST|\bMethod\s+POST\b|\bPOST\b)'
  UploadZipContent = $e.Message -match '(?i)(-ContentType\s+["'']?application/zip|application/zip)'
  CryptoStrong     = $e.Message -match '(?i)(System\.Security\.Cryptography|AesManaged|AesCng|AES|CryptoStream|CreateEncryptor|CreateDecryptor|Rfc2898DeriveBytes|SHA256|\.aes)'
}

$e = Get-WinEvent -FilterHashtable @{
  LogName = 'Microsoft-Windows-PowerShell/Operational'
  Id = 4104
  StartTime = $runStart
} | Where-Object {
  $_.Message -match 'TFM candidate v3'
} | Select-Object -First 1

[pscustomobject]@{
  UploadHttpRegex       = $e.Message -match '(?i)(Invoke-WebRequest|\biwr\b|\bwget\b|\bcurl\b)'
  UploadFileRegex       = $e.Message -match '(?i)(-InFile\b|\bInFile\b)'
  UploadPostRegex       = $e.Message -match '(?i)(-Method\s+POST|\bMethod\s+POST\b|\bPOST\b)'
  UploadZipContentRegex = $e.Message -match '(?i)(-ContentType\s+["'']?application/zip|application/zip)'
  HashEvidenceRegex     = $e.Message -match '(?i)(Get-FileHash|SHA256|SHA1|MD5|LocalSHA256|FileHash)'
  CryptoEncryptionRegex = $e.Message -match '(?i)(System\.Security\.Cryptography|AesManaged|AesCng|AES|CryptoStream|CreateEncryptor|CreateDecryptor|Rfc2898DeriveBytes|\.aes)'
}
